def minEditCost(s, t, insertCost, deleteCost, replaceCost):
    n = len(t)
    prev = [j * insertCost for j in range(n + 1)]
    for i in range(1, len(s) + 1):
        a = s[i - 1]
        cur = [i * deleteCost] + [0] * n
        for j in range(1, n + 1):
            if a == t[j - 1]:
                x = prev[j - 1]
            else:
                x = prev[j - 1] + replaceCost
            y = prev[j] + deleteCost
            if y < x:
                x = y
            y = cur[j - 1] + insertCost
            if y < x:
                x = y
            cur[j] = x
        prev = cur
    return prev[n]
